<?php
/** Reviewed, branch-scoped partner obligations; historical cash is never inferred. */
function partner_contract(int $id,bool $lock=false): array {global $pdo;$q=$pdo->prepare('SELECT * FROM mudaraba_contracts WHERE id=? AND shop_id=?'.($lock?finance_lock():''));$q->execute([$id,shop_id()]);$c=$q->fetch();if(!$c)throw new RuntimeException('Partnership contract unavailable.',403);return $c;}
function partner_account(int $contract,bool $lock=false): ?array {global $pdo;$q=$pdo->prepare('SELECT * FROM partnership_accounts WHERE shop_id=? AND contract_id=?'.($lock?finance_lock():''));$q->execute([shop_id(),$contract]);return $q->fetch()?:null;}
function partner_codes(int $id): array {return ['principal'=>'PP'.$id,'profit'=>'PR'.$id,'recovery'=>'PV'.$id];}
function partner_balances(int $contract): array {global $pdo;$c=partner_contract($contract);$result=[];foreach(partner_codes($contract) as $kind=>$code){$q=$pdo->prepare('SELECT COALESCE(SUM(d.debit-d.credit),0) FROM journal_details d JOIN journal_headers h ON h.id=d.journal_id AND h.shop_id=d.shop_id WHERE d.shop_id=? AND d.account_code=? AND h.currency_code=?');$q->execute([shop_id(),$code,$c['currency_code']]);$value=dec_round($q->fetchColumn());$result[$kind]=$kind==='recovery'?$value:dec_mul($value,-1);}return $result;}
function partner_share(array $c): string {if(!(int)($c['profit_known']??1))throw new InvalidArgumentException(__t('Review the contract profit across currencies before settling.','پیش از تسویه، مفاد قرارداد با ارزهای متفاوت را بررسی کنید.','لومړی د بېلابېلو اسعارو ګټه تایید کړئ.'));return dec_div(dec_mul($c['total_profit_amount'],$c['partner_profit_rate'],6),100);}
function partner_review(int $contract,$principal,$profit,string $note): int {
 global $pdo;domain_require('mudaraba.settle');domain_require('mudaraba.approve');domain_consume_exact('mudaraba.settle');domain_require('accounting.approve');$principal=finance_amount($principal,true);$profit=dec_round($profit);if(abs(dec_units($profit))>100000000000000||mb_strlen(trim($note))<10||mb_strlen($note)>1000)throw new InvalidArgumentException('Enter verified opening balances and a review note.');
 return finance_atomic(function()use($pdo,$contract,$principal,$profit,$note){$c=partner_contract($contract,true);if(partner_account($contract,true))throw new InvalidArgumentException('Partnership opening was already reviewed. Use a separate adjustment document.');$share=partner_share($c);finance_seed(shop_id());$codes=partner_codes($contract);foreach($codes as $kind=>$code)$pdo->prepare('INSERT INTO ledger_accounts (shop_id,code,name,account_type) VALUES (?,?,?,?)')->execute([shop_id(),$code,'Partner '.$kind.' #'.$contract,$kind==='recovery'?'asset':'liability']);$pdo->prepare('INSERT INTO partnership_accounts (shop_id,contract_id,opening_principal,opening_profit,recognized_share,review_note,created_by) VALUES (?,?,?,?,?,?,?)')->execute([shop_id(),$contract,$principal,$profit,$share,$note,auth_user()['id']]);$id=(int)$pdo->lastInsertId();$lines=[];if(dec_units($principal)>0){$lines[]=[$codes['principal'],0,$principal];$lines[]=['3900',$principal,0];}if(dec_units($profit)>0){$lines[]=[$codes['profit'],0,$profit];$lines[]=['3900',$profit,0];}elseif(dec_units($profit)<0){$amount=dec_mul($profit,-1);$lines[]=[$codes['recovery'],$amount,0];$lines[]=['3900',0,$amount];}if($lines)finance_post('partner_opening',$id,$c['currency_code'],date('Y-m-d'),'Reviewed partnership opening',$lines);domain_audit('partnership_opening_reviewed','mudaraba',$contract,['principal'=>$principal,'profit_net'=>$profit,'recognized_share'=>$share,'review_note'=>$note]);return $id;});
}
/** Recognize only the change since the reviewed baseline; recover overpaid profit as a receivable. */
function partner_share_sync(int $contract,string $sourceType,$sourceId): void {
 global $pdo;finance_atomic(function()use($pdo,$contract,$sourceType,$sourceId){$c=partner_contract($contract,true);$account=partner_account($contract,true);if(!$account)return;if(!(int)($c['profit_known']??1))return;$share=partner_share($c);$delta=dec_sub($share,$account['recognized_share']);if(dec_units($delta)===0)return;$balances=partner_balances($contract);$codes=partner_codes($contract);$amount=dec_units($delta)<0?dec_mul($delta,-1):$delta;$lines=[];
  if(dec_units($delta)>0){$recovery=dec_units($balances['recovery'])<dec_units($amount)?$balances['recovery']:$amount;$payable=dec_sub($amount,$recovery);$lines[]=['3100',$amount,0];if(dec_units($recovery)>0)$lines[]=[$codes['recovery'],0,$recovery];if(dec_units($payable)>0)$lines[]=[$codes['profit'],0,$payable];}
  else{$reversal=dec_units($balances['profit'])<dec_units($amount)?$balances['profit']:$amount;$recovery=dec_sub($amount,$reversal);$lines[]=['3100',0,$amount];if(dec_units($reversal)>0)$lines[]=[$codes['profit'],$reversal,0];if(dec_units($recovery)>0)$lines[]=[$codes['recovery'],$recovery,0];}
  finance_post('partner_share',$sourceType.'-'.$sourceId.'-'.$contract,$c['currency_code'],date('Y-m-d'),'Partner profit allocation adjustment',$lines);$pdo->prepare('UPDATE partnership_accounts SET recognized_share=? WHERE shop_id=? AND contract_id=?')->execute([$share,shop_id(),$contract]);domain_audit('partner_profit_allocated','mudaraba',$contract,['share_change'=>$delta,'recognized_share'=>$share]);
 });
}
function partner_available(int $contract,string $kind,string $date): string {
 global $pdo;$c=partner_contract($contract);$code=partner_codes($contract)[$kind];$delta=$kind==='recovery'?'d.debit-d.credit':'d.credit-d.debit';$q=$pdo->prepare("SELECT h.posting_date,SUM($delta) AS change_amount FROM journal_details d JOIN journal_headers h ON h.id=d.journal_id AND h.shop_id=d.shop_id WHERE d.shop_id=? AND d.account_code=? AND h.currency_code=? GROUP BY h.posting_date ORDER BY h.posting_date");$q->execute([shop_id(),$code,$c['currency_code']]);$running='0.00';$future=[];foreach($q->fetchAll() as $row){if($row['posting_date']<=$date)$running=dec_add($running,$row['change_amount']);else $future[]=$row;}$minimum=$running;foreach($future as $row){$running=dec_add($running,$row['change_amount']);if(dec_units($running)<dec_units($minimum))$minimum=$running;}return $minimum;
}
function partner_cash(int $contract,string $kind,int $cash,$amount,string $date,string $request,string $note): int {
 global $pdo;domain_require('mudaraba.settle');domain_require('mudaraba.approve');domain_consume_exact('mudaraba.settle');domain_require('treasury.approve');if(!in_array($kind,['funding','principal','profit','recovery'],true)||mb_strlen(trim($note))<3)throw new InvalidArgumentException('Choose a settlement type and reference.');$amount=finance_amount($amount);finance_date($date);
 return finance_atomic(function()use($pdo,$contract,$kind,$cash,$amount,$date,$request,$note){$c=partner_contract($contract,true);if(!partner_account($contract,true))throw new InvalidArgumentException('Review the partnership opening first.');funds_account($cash,$c['currency_code']);$codes=partner_codes($contract);$code=$codes[$kind==='funding'?'principal':$kind];$direction=in_array($kind,['funding','recovery'],true)?'in':'out';$source='partner_'.$kind;$q=$pdo->prepare('SELECT id FROM fund_transactions WHERE shop_id=? AND request_key=? AND source_type=? AND source_id=?');$q->execute([shop_id(),$request,$source,$contract]);if($q->fetchColumn())return funds_record($cash,$direction,$amount,$code,$source,$contract,$request,$date,$note);
  if(in_array($kind,['profit','recovery'],true))partner_share($c);partner_share_sync($contract,'cash',$request);$b=partner_balances($contract);if($kind!=='funding'&&(dec_units($amount)>dec_units($b[$kind])||dec_units($amount)>dec_units(partner_available($contract,$kind,$date))))throw new InvalidArgumentException(__t('Settlement exceeds the verified partner balance.','تسویه از ماندهٔ تأییدشدهٔ شریک بیشتر است.','تصفیه د شریک له تایید شوې ماندې زیاته ده.'));$id=funds_record($cash,$direction,$amount,$code,$source,$contract,$request,$date,$note);
  if($kind==='principal')$pdo->prepare('UPDATE mudaraba_contracts SET returned_capital=returned_capital+? WHERE id=? AND shop_id=?')->execute([$amount,$contract,shop_id()]);
  if($kind==='profit')$pdo->prepare('UPDATE mudaraba_contracts SET paid_profit_to_partner=paid_profit_to_partner+? WHERE id=? AND shop_id=?')->execute([$amount,$contract,shop_id()]);
  if($kind==='recovery'){$net=dec_sub($c['paid_profit_to_partner'],$amount);if(dec_units($net)<0)$net='0.00';$pdo->prepare('UPDATE mudaraba_contracts SET paid_profit_to_partner=? WHERE id=? AND shop_id=?')->execute([$net,$contract,shop_id()]);}
  if($c['status']==='settled')$pdo->prepare("UPDATE mudaraba_contracts SET status='active',settlement_date=NULL WHERE id=? AND shop_id=?")->execute([$contract,shop_id()]);return $id;
 });
}
function partner_contract_hash(array $c): string {$b=partner_balances((int)$c['id']);return hash('sha256',json_encode([$c['id'],$c['capital_amount'],$c['total_sales_amount'],$c['total_profit_amount'],$c['paid_profit_to_partner'],$c['returned_capital'],$c['currency_code'],$c['status'],$b],JSON_THROW_ON_ERROR));}
function partner_review_return(int $sale,int $contract,string $note): void {
 global $pdo;domain_require('mudaraba.review_returns');domain_require('mudaraba.approve');domain_consume_exact('mudaraba.review_returns');if(mb_strlen(trim($note))<10||mb_strlen($note)>1000)throw new InvalidArgumentException('Explain the reviewed ownership and profit recovery agreement.');finance_atomic(function()use($pdo,$sale,$contract,$note){$c=partner_contract($contract,true);if(!partner_account($contract,true))throw new InvalidArgumentException('Review the partnership opening first.');$q=$pdo->prepare('SELECT i.id FROM sale_items i JOIN stock s ON s.id=i.stock_id AND s.shop_id=i.shop_id WHERE i.sale_id=? AND i.shop_id=? AND s.mudaraba_id=?');$q->execute([$sale,shop_id(),$contract]);if(!$q->fetchColumn())throw new InvalidArgumentException('The invoice has no item from this contract.');$q=$pdo->prepare('SELECT id FROM partnership_return_reviews WHERE shop_id=? AND sale_id=? AND contract_id=?');$q->execute([shop_id(),$sale,$contract]);$hash=partner_contract_hash($c);if($id=$q->fetchColumn())$pdo->prepare('UPDATE partnership_return_reviews SET contract_hash=?,review_note=?,created_by=?,created_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$hash,$note,auth_user()['id'],$id]);else $pdo->prepare('INSERT INTO partnership_return_reviews (shop_id,sale_id,contract_id,contract_hash,review_note,created_by) VALUES (?,?,?,?,?,?)')->execute([shop_id(),$sale,$contract,$hash,$note,auth_user()['id']]);domain_audit('partnership_return_reviewed','sale',$sale,['contract_id'=>$contract,'review_note'=>$note]);});
}
function partner_return_allowed(int $sale,array $contract): bool {global $pdo;if(!partner_account((int)$contract['id']))return false;$q=$pdo->prepare('SELECT contract_hash FROM partnership_return_reviews WHERE shop_id=? AND sale_id=? AND contract_id=?');$q->execute([shop_id(),$sale,$contract['id']]);$hash=$q->fetchColumn();return $hash&&hash_equals($hash,partner_contract_hash($contract));}
function partner_close(int $contract): void {
 global $pdo;domain_require('mudaraba.settle');domain_require('mudaraba.approve');domain_consume_exact('mudaraba.settle');finance_atomic(function()use($pdo,$contract){$c=partner_contract($contract,true);if(!partner_account($contract,true))throw new InvalidArgumentException('Review the partnership opening first.');partner_share($c);partner_share_sync($contract,'close',bin2hex(random_bytes(16)));foreach(partner_balances($contract) as $amount)if(dec_units($amount)!==0)throw new InvalidArgumentException('Settle all principal, profit and recoveries before closing.');$q=$pdo->prepare('SELECT id FROM stock WHERE shop_id=? AND mudaraba_id=? AND (quantity>0 OR reserved_qty>0)');$q->execute([shop_id(),$contract]);if($q->fetchColumn())throw new InvalidArgumentException('Sell, return or release remaining stock before closing.');$pdo->prepare("UPDATE mudaraba_contracts SET status='settled',settlement_date=? WHERE id=? AND shop_id=?")->execute([date('Y-m-d'),$contract,shop_id()]);domain_audit('partnership_closed','mudaraba',$contract);});
}

/** A named approval is needed when profit cannot be derived from same-currency source documents. */
function partner_review_profit(int $contract,$profit,string $note,string $request): int {
 global $pdo;domain_require('mudaraba.settle');domain_require('mudaraba.approve');domain_consume_exact('mudaraba.settle');domain_require('accounting.approve');$profit=dec_round($profit);if(abs(dec_units($profit))>100000000000000||mb_strlen(trim($note))<10||mb_strlen($note)>1000||!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$request))throw new InvalidArgumentException('Enter the verified contract-currency profit and supporting reference.');$hash=hash('sha256',json_encode([$contract,$profit,$note],JSON_THROW_ON_ERROR));
 return finance_atomic(function()use($pdo,$contract,$profit,$note,$request,$hash){$c=partner_contract($contract,true);$q=$pdo->prepare('SELECT id,content_hash FROM partner_profit_reviews WHERE shop_id=? AND request_key=?');$q->execute([shop_id(),$request]);if($old=$q->fetch()){if(!hash_equals($old['content_hash'],$hash))throw new InvalidArgumentException('Profit review request changed.');return (int)$old['id'];}finance_seed(shop_id());$q=$pdo->prepare('SELECT closed_until FROM financial_periods WHERE shop_id=?'.finance_lock());$q->execute([shop_id()]);$closed=$q->fetchColumn();if($closed&&date('Y-m-d')<=$closed)throw new InvalidArgumentException('Review period is closed.');$pdo->prepare('INSERT INTO partner_profit_reviews (shop_id,contract_id,request_key,content_hash,previous_profit,verified_profit,review_note,created_by) VALUES (?,?,?,?,?,?,?,?)')->execute([shop_id(),$contract,$request,$hash,$c['total_profit_amount'],$profit,$note,auth_user()['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE mudaraba_contracts SET total_profit_amount=?,profit_known=1 WHERE id=? AND shop_id=?')->execute([$profit,$contract,shop_id()]);partner_share_sync($contract,'review',$id);domain_audit('partner_profit_reviewed','mudaraba',$contract,['previous_profit'=>$c['total_profit_amount'],'verified_profit'=>$profit,'reference'=>$note]);return $id;});
}
function partner_review_purchase_return(int $purchase,int $contract,string $note): void {
 global $pdo;domain_require('mudaraba.review_returns');domain_require('mudaraba.approve');domain_consume_exact('mudaraba.review_returns');if(mb_strlen(trim($note))<10||mb_strlen($note)>1000)throw new InvalidArgumentException('Explain the supplier return and unchanged principal repayment obligation.');finance_atomic(function()use($pdo,$purchase,$contract,$note){$c=partner_contract($contract,true);if(!partner_account($contract,true))throw new InvalidArgumentException('Review the partnership opening first.');$q=$pdo->prepare('SELECT id FROM inventory_purchase_items WHERE shop_id=? AND purchase_id=? AND mudaraba_id=?');$q->execute([shop_id(),$purchase,$contract]);if(!$q->fetchColumn())throw new InvalidArgumentException('Purchase has no items from this contract.');$hash=partner_contract_hash($c);$q=$pdo->prepare('SELECT id FROM partnership_purchase_reviews WHERE shop_id=? AND purchase_id=? AND contract_id=?');$q->execute([shop_id(),$purchase,$contract]);if($id=$q->fetchColumn())$pdo->prepare('UPDATE partnership_purchase_reviews SET contract_hash=?,review_note=?,created_by=?,created_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$hash,$note,auth_user()['id'],$id]);else $pdo->prepare('INSERT INTO partnership_purchase_reviews (shop_id,purchase_id,contract_id,contract_hash,review_note,created_by) VALUES (?,?,?,?,?,?)')->execute([shop_id(),$purchase,$contract,$hash,$note,auth_user()['id']]);domain_audit('partner_purchase_return_reviewed','purchase',$purchase,['contract_id'=>$contract,'review_note'=>$note]);});
}
function partner_purchase_return_allowed(int $purchase,array $contract): bool {global $pdo;if(!partner_account((int)$contract['id']))return false;$q=$pdo->prepare('SELECT contract_hash FROM partnership_purchase_reviews WHERE shop_id=? AND purchase_id=? AND contract_id=?');$q->execute([shop_id(),$purchase,$contract['id']]);$hash=$q->fetchColumn();return $hash&&hash_equals($hash,partner_contract_hash($contract));}
/** Repaid partner goods may be released into business-owned destination stock only with an explicit agreement. */
function partner_transfer_review(array $stock,array $approval): array {
 domain_require('mudaraba.release_stock');domain_require('mudaraba.approve');domain_consume_exact('mudaraba.release_stock');domain_require('inventory.approve');if(!empty($stock['partner_id'])||empty($stock['mudaraba_id']))throw new InvalidArgumentException('A general-partner position needs a contract settlement before release.');$c=partner_contract((int)$stock['mudaraba_id'],true);if(!partner_account((int)$c['id'],true))throw new InvalidArgumentException('Review the partnership opening first.');partner_share_sync((int)$c['id'],'release',bin2hex(random_bytes(16)));foreach(partner_balances((int)$c['id']) as $amount)if(dec_units($amount)!==0)throw new InvalidArgumentException(__t('Settle principal, profit and recoveries before releasing partner goods.','پیش از آزادکردن جنس شریک، اصل سرمایه، مفاد و اضافه‌پرداخت را تسویه کنید.','لومړی د شریک پانګه، ګټه او اضافي پیسې تصفیه کړئ.'));$note=trim((string)($approval['ownership_review']??''));if(($approval['ownership_released']??'')!=='1'||mb_strlen($note)<10||mb_strlen($note)>1000)throw new InvalidArgumentException(__t('Record the partner agreement releasing claims on the transferred goods.','توافق شریک برای ختم حق او بر اجناس انتقالی را ثبت و تأیید کنید.','د شریک د حق د ختمېدو موافقه تایید کړئ.'));return [$note,partner_contract_hash($c),(int)auth_user()['id']];
}
function partner_validate_transfer(array $transfer,array $stock): void {
 global $pdo;if(!empty($stock['partner_id'])||empty($stock['mudaraba_id'])||empty($transfer['ownership_hash'])||empty($transfer['ownership_reviewed_by']))throw new InvalidArgumentException('Partner ownership release was not approved.');$branch=(int)$transfer['source_shop_id'];$q=$pdo->prepare('SELECT * FROM mudaraba_contracts WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$stock['mudaraba_id'],$branch]);$c=$q->fetch();if(!$c)throw new InvalidArgumentException('Source contract unavailable.');$q=$pdo->prepare('SELECT id FROM partnership_accounts WHERE shop_id=? AND contract_id=?');$q->execute([$branch,$c['id']]);if(!$q->fetchColumn())throw new InvalidArgumentException('Source partnership has no reviewed settlement.');$balances=[];foreach(partner_codes((int)$c['id']) as $kind=>$code){$q=$pdo->prepare('SELECT COALESCE(SUM(d.debit-d.credit),0) FROM journal_details d JOIN journal_headers h ON h.id=d.journal_id AND h.shop_id=d.shop_id WHERE d.shop_id=? AND d.account_code=? AND h.currency_code=?');$q->execute([$branch,$code,$c['currency_code']]);$amount=dec_round($q->fetchColumn());$balances[$kind]=$kind==='recovery'?$amount:dec_mul($amount,-1);if(dec_units($amount)!==0)throw new InvalidArgumentException('Partner balance changed; cancel and review the transfer again.');}$hash=hash('sha256',json_encode([$c['id'],$c['capital_amount'],$c['total_sales_amount'],$c['total_profit_amount'],$c['paid_profit_to_partner'],$c['returned_capital'],$c['currency_code'],$c['status'],$balances],JSON_THROW_ON_ERROR));if(!hash_equals($transfer['ownership_hash'],$hash))throw new InvalidArgumentException('Ownership agreement changed; review the transfer again.');
}
